 const staticRoot=new T.Group();scene.add(staticRoot);const animated=[],emissive=[],pickables=[],placements=[],selectable=[],rides=[],buckets=new Map(),windows=[],frames=[];let seed=46521;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};
