 const wallMats=new Map(),roofMats=new Map();function wall(land,id){const key=land+id;if(!wallMats.has(key)){const mat=materials.wall.clone();mat.color.set(colors[land][id%colors[land].length]);mat.envMapIntensity=.38;mat.roughness=1;mat.normalScale.set(.7,.7);mat.onBeforeCompile=s=>{s.vertexShader='varying vec3 vFacadePosition;\n'+s.vertexShader;s.vertexShader=s.vertexShader.replace('#include <worldpos_vertex>','#include <worldpos_vertex>\nvFacadePosition=(modelMatrix*vec4(transformed,1.)).xyz;');s.fragmentShader='varying vec3 vFacadePosition;\n'+s.fragmentShader;s.fragmentShader=s.fragmentShader.replace('#include <color_fragment>','#include <color_fragment>\nfloat wear=(sin(vFacadePosition.x*1.8+sin(vFacadePosition.z*2.1))+sin(vFacadePosition.y*2.7+vFacadePosition.z))*.012;float foot=1.-smoothstep(.05,.65,vFacadePosition.y);diffuseColor.rgb*=1.+wear-foot*.11;');};mat.customProgramCacheKey=()=> 'plaster-wear-v7';wallMats.set(key,mat);}return wallMats.get(key);}
 const dark=new T.MeshStandardMaterial({color:'#263936',roughness:.28,metalness:.18,emissive:'#e8b76f',emissiveIntensity:0}),trim=new T.MeshStandardMaterial({color:'#dbd0bc',roughness:.85}),metal=new T.MeshStandardMaterial({color:'#3f4746',metalness:.6,roughness:.5}),gold=new T.MeshStandardMaterial({color:'#b99a58',metalness:.65,roughness:.4});emissive.push({material:dark,intensity:.52});
