 const footprintById=new Map();for(const f of data.features){if(f.properties.layer!=='building'||f.geometry.type!=='Polygon')continue;const ring=f.geometry.coordinates[0],p=centroid(ring),land=region(p),a=Math.abs(area(ring)),id=f.properties.osm_id;footprintById.set(id,{ring,p,feature:f});if(data.landmarks.some(l=>['carousel','dumbo','rex','slinky','woody','jetpacks'].includes(l.key)&&inside([l.x,l.z],ring)))continue;if(id===494348161||id===754485727||registry.some(v=>v.footprint===id||v.footprints?.includes(id)))continue;
 const height=f.properties.height_m??Math.min(f.properties.height_estimate_m??7.5,18),mat=wall(land,Math.floor(rand()*3)),roof=roofMats.get(land)||materials.roof.clone();roofMats.set(land,roof);roof.color.set(land==='tomorrow'?'#9aa7ae':land==='adventure'?'#7b7458':land==='treasure'?'#896552':'#748182');selectable.push({feature:f,ring,height});if(f.properties.tags?.building==='roof'){const canopy=add(extrude(ring,.26,3),roof);canopy.position.y=height;for(let i=0;i<ring.length-1;i++){const u=ring[i],v=ring[i+1],len=distance(u,v),count=Math.max(1,Math.ceil(len/7));for(let n=0;n<count;n++)box(.24,height,.24,metal,T.MathUtils.lerp(u[0],v[0],n/count),.04,T.MathUtils.lerp(u[1],v[1],n/count));const beam=box(len,.28,.24,metal,(u[0]+v[0])/2,height-.2,(u[1]+v[1])/2);beam.rotation.y=Math.atan2(-(v[1]-u[1]),v[0]-u[0]);}continue;}buildFacade({ring,height,land,wall:mat,roof,trim,add,box,paths,placements,kit,rand});}
 // Outdoor ride structures occupy their mapped locations; moving parts are separate.
 const spot=key=>data.landmarks.find(p=>p.key===key),makeRide=key=>{if(rideAssets[key]||['jetpacks','slinky'].includes(key))return null;const s=spot(key);if(!s)return null;const g=new T.Group();g.position.set(s.x,.15,s.z);scene.add(g);g.userData.landmark=key;rides.push({key,group:g});return{g,s};};
 const disc=(r,h,mat,x,y,z,parent)=>{const m=add(new T.CylinderGeometry(r,r,h,64),mat,parent);m.position.set(x,y+h/2,z);return m;};
