 {const r=makeRide('carousel');if(r){const{g}=r;disc(13,.35,trim,0,0,0,g);disc(11.8,.45,wall('gardens',0),0,.35,0,g);const rot=new T.Group();g.add(rot);for(let i=0;i<32;i++){const a=i/32*Math.PI*2,rad=i%2?8.8:6.2;const h=horse(rot,Math.cos(a)*rad,Math.sin(a)*rad);h.rotation.y=-a;animated.push(t=>h.position.y=.85+Math.sin(t*1.2+i)*.17);}for(let i=0;i<12;i++){const a=i/12*Math.PI*2;const p=add(new T.CylinderGeometry(.16,.22,6.7,12),trim,g);p.position.set(Math.cos(a)*11.1,3.8,Math.sin(a)*11.1);}const roof=add(new T.ConeGeometry(13.4,5.4,64),materials.roof,g);roof.position.y=9.25;disc(13.3,.38,trim,0,6.35,0,g);const crown=add(new T.SphereGeometry(.55,18,12),gold,g);crown.position.y=12.35;animated.push(t=>rot.rotation.y=t*.045);}}
 {const r=makeRide('rex');if(r){const{g}=r;const orange=new T.MeshStandardMaterial({color:'#cc6b2b',roughness:.52,metalness:.3}),darkTrack=new T.MeshStandardMaterial({color:'#454c4f',metalness:.6,roughness:.5});const curve=[];for(let i=0;i<=64;i++){const a=Math.PI*.06+i/64*Math.PI*.88;curve.push(new T.Vector3(Math.cos(a)*24,29-Math.sin(a)*27,0));}for(const z of [-1.8,1.8])tube(curve.map(p=>p.clone().add(new T.Vector3(0,0,z))),.26,orange,g,140);curve.forEach((p,i)=>{if(i%3)return;const m=box(.2,.25,3.7,darkTrack,p.x,p.y-.4,0,g);m.rotation.z=Math.atan2(curve[Math.min(i+1,64)].y-p.y,curve[Math.min(i+1,64)].x-p.x);if(i%6===0){for(const z of[-2.5,2.5]){const pole=add(new T.CylinderGeometry(.28,.34,p.y,12),metal,g);pole.position.set(p.x,p.y/2,z);}}});const car=new T.Group();g.add(car);box(5,1.1,3.7,new T.MeshStandardMaterial({color:'#aabb43',roughness:.4}),0,0,0,car);for(let i=0;i<4;i++)box(.8,.9,2.5,trim,(i-1.5)*1.05,.9,0,car);const rcCurve=new T.CatmullRomCurve3(curve);animated.push(t=>{const u=.5+Math.sin(t*.3)*.39,p=rcCurve.getPoint(u),d=rcCurve.getTangent(u);car.position.copy(p);car.rotation.z=Math.atan2(d.y,d.x);});g.rotation.y=-.4;}}
 for(const key of ['dumbo','jetpacks','slinky','woody']){const r=makeRide(key);if(!r)continue;const{g}=r,rad=key==='dumbo'?12:key==='jetpacks'?16:10,mat=wall(key==='jetpacks'?'tomorrow':'toy',0);disc(rad+2,.25,trim,0,0,0,g);const rotor=new T.Group();g.add(rotor);disc(2,5,mat,0,.5,0,g);for(let i=0;i<12;i++){const a=i/12*Math.PI*2;if(key==='slinky'){const p=add(new T.TorusGeometry(2,.16,8,16),metal,rotor);p.position.set(Math.cos(a)*8,1.7,Math.sin(a)*8);p.rotation.y=-a;continue;}const endpoint=new T.Vector3(Math.cos(a)*rad,3.2,Math.sin(a)*rad);tube([new T.Vector3(0,4.5,0),endpoint],.12,metal,rotor,8);const pod=add(new T.SphereGeometry(.9,16,12),mat,rotor);pod.scale.set(1.3,.65,1.65);pod.position.copy(endpoint);pod.rotation.y=-a;if(key==='dumbo'){const earMat=new T.MeshStandardMaterial({color:'#aeb8bd',roughness:.7});for(const side of [-1,1]){const ear=add(new T.SphereGeometry(.62,12,8),earMat,pod);ear.scale.set(.25,.85,1);ear.position.set(side*.8,.3,0);}const trunk=add(new T.CylinderGeometry(.12,.2,.75,10),earMat,pod);trunk.position.set(0,-.15,-.8);trunk.rotation.x=-.5;}}animated.push(t=>rotor.rotation.y=t*(key==='jetpacks'?.06:.035));}
 // The outdoor mine train rails follow the mapped horizontal alignment.
 for(const f of data.features){if(f.properties.layer!=='ride_track'||f.properties.tags?.tunnel==='yes'||f.geometry.type!=='LineString')continue;const coords=f.geometry.coordinates;if(coords.length<3||distance(centroid(coords),[16,-210])>170)continue;const curve=new T.CatmullRomCurve3(coords.map((p,i)=>new T.Vector3(p[0],3.5+Math.sin(i*.43)*1.5,p[1]))),length=curve.getLength(),samples=Math.ceil(length/.75),rails=[[],[]];
 for(let i=0;i<=samples;i++){const u=i/samples,p=curve.getPointAt(u),t=curve.getTangentAt(u),n=new T.Vector3(-t.z,0,t.x).normalize();rails[0].push(p.clone().addScaledVector(n,.55));rails[1].push(p.clone().addScaledVector(n,-.55));const sleeper=box(1.45,.14,.16,metal,p.x,p.y-.15,p.z);sleeper.rotation.y=Math.atan2(-n.z,n.x);if(i%8===0){for(const side of[-1,1]){const q=p.clone().addScaledVector(n,side*.8),post=add(new T.CylinderGeometry(.16,.23,q.y,10),wall('fantasy',0));post.position.set(q.x,q.y/2,q.z);}}}for(const rail of rails)tube(rail,.075,metal,staticRoot,Math.max(70,samples*2));
 }
